import subprocess
def run(args, inp=None):
    p=subprocess.run(["./executable"]+args, input=inp, capture_output=True, text=True)
    lines=p.stdout.splitlines(True)
    rest=''.join(lines[1:]) if lines else ''
    return rest
for i in range(10):
    print(repr(run(["-S"], "a@b.com 1.2.3.4 https://example.com\n")))
print("--- -C -T no flags")
for i in range(10):
