print("--- -C no flags")
for i in range(10):
    print(repr(run(["-S","-C"], "a@b.com 1.2.3.4 https://example.com\n")))
print("--- -e -i -C -T")
for i in range(10):
    print(repr(run(["-S","-C","-T","-e","-i"], "a@b.com 1.2.3.4 c@d.com 5.6.7.8\n")))
