use serde::{Deserialize, Serialize};
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read, Write};
use std::net::{TcpStream, ToSocketAddrs};
use std::path::Path;
use std::process::{self, Child, ChildStdin, ChildStdout, Command, Stdio};
use url::Url;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Plugin {
    pub arg_long_name: String,
    pub help_message: String,
    pub content_type: String,
    pub source_url: String,
    pub version: String,
    pub regex: String,
}

fn prompt_exit() {
    println!("[+] Do you want to exit? (y/n): ");
    let mut input = String::new();
    let _ = io::stdin().read_line(&mut input);
    match input.trim().to_lowercase().as_str() {
        "y" => process::exit(1),
        "n" => {}
        _ => {
            println!("[-] Invalid input. Please enter 'y' or 'n'.");
            prompt_exit();
        }
    }
}

pub fn get_plugin_path() -> String {
    let home = std::env::var("HOME").unwrap_or_else(|err| {
        panic!(
            "Home directory not found. Failed to read environmental variable: `HOME`.: {:?}",
            err
        )
    });
    format!("{}/.DataSurgeon/plugins.json", home)
}

pub fn load_plugins() -> Option<Vec<Plugin>> {
    let plugin_path = get_plugin_path();
    if !Path::new(&plugin_path).exists() {
        println!(
            "Failed to open plugins.json file. PLUGIN_PATH: {}",
            plugin_path
        );
        return None;
    }

    let mut file = match File::open(&plugin_path) {
        Ok(file) => file,
        Err(_) => {
            println!("[-] Error: Failed to open plugins.json file.");
            prompt_exit();
            return Some(Vec::new());
        }
    };

    let mut contents = String::new();
    if file.read_to_string(&mut contents).is_err() {
        println!("[-] Error: Failed to read from plugins.json file.");
        prompt_exit();
        return Some(Vec::new());
    }

    match serde_json::from_str::<Vec<Plugin>>(&contents) {
        Ok(plugins) => Some(plugins),
        Err(_) => {
            println!(
                "[-] Error: Failed to parse plugins.json. Please ensure all required fields are present."
            );
            prompt_exit();
            Some(Vec::new())
        }
    }
}

pub fn save_plugins(plugins: &[Plugin]) {
    let plugin_path = get_plugin_path();
    let mut file = match File::create(&plugin_path) {
        Ok(file) => file,
        Err(_) => {
            println!("[-] Error: Failed to open plugins.json file for writing.");
            process::exit(1);
        }
    };
    let contents = serde_json::to_string(plugins).unwrap();
    let _ = file.write_all(contents.as_bytes());
}

pub fn list_plugins() {
    let plugins = load_plugins().unwrap_or_default();
    let plugin_path = get_plugin_path();
    if plugins.is_empty() {
        println!("No plugins found. Plugin File: {}", plugin_path);
        return;
    }

    let source_width = plugins
        .iter()
        .map(|plugin| plugin.source_url.len())
        .max()
        .unwrap_or(0)
        .max("Source URL".len());
    let version_width = plugins
        .iter()
        .map(|plugin| plugin.version.len())
        .max()
        .unwrap_or(0)
        .max("Version".len());
    let arg_width = plugins
        .iter()
        .map(|plugin| plugin.arg_long_name.len())
        .max()
        .unwrap_or(0)
        .max("Argument Long Name".len());

    println!("Plugin File: {}\n", plugin_path);
    println!(
        "{:<source_width$} | {:<version_width$} | {:<arg_width$}",
        "Source URL",
        "Version",
        "Argument Long Name",
        source_width = source_width,
        version_width = version_width,
        arg_width = arg_width
    );
    for plugin in &plugins {
        println!(
            "{:<source_width$} | {:<version_width$} | {:<arg_width$}",
            plugin.source_url,
            plugin.version,
            plugin.arg_long_name,
            source_width = source_width,
            version_width = version_width,
            arg_width = arg_width
        );
    }
}

fn normalize_url(url: &str) -> String {
    url.to_lowercase()
        .replace("https://", "")
        .replace("http://", "")
        .trim_end_matches('/')
        .to_string()
}

pub fn remove_plugin(url: &str) {
    let mut plugins = load_plugins().unwrap_or_default();
    let original_len = plugins.len();
    let normalized = normalize_url(url);
    plugins.retain(|plugin| normalize_url(&plugin.source_url) != normalized);
    if plugins.len() != original_len {
        save_plugins(&plugins);
        println!("[*] Removed plugin: {}", url);
    }
}

struct TlsStream {
    child: Child,
    stdin: Option<ChildStdin>,
    stdout: Option<ChildStdout>,
}

impl Read for TlsStream {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        match self.stdout.as_mut() {
            Some(stdout) => stdout.read(buf),
            None => Ok(0),
        }
    }
}

impl Write for TlsStream {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        match self.stdin.as_mut() {
            Some(stdin) => stdin.write(buf),
            None => Err(io::Error::new(io::ErrorKind::BrokenPipe, "tls input closed")),
        }
    }

    fn flush(&mut self) -> io::Result<()> {
        match self.stdin.as_mut() {
            Some(stdin) => stdin.flush(),
            None => Ok(()),
        }
    }
}

impl Drop for TlsStream {
    fn drop(&mut self) {
        self.stdin.take();
        self.stdout.take();
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

enum Conn {
    Plain(TcpStream),
    Tls(Box<TlsStream>),
}

impl Read for Conn {
    fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
        match self {
            Conn::Plain(stream) => stream.read(buf),
            Conn::Tls(stream) => stream.read(buf),
        }
    }
}

impl Write for Conn {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        match self {
            Conn::Plain(stream) => stream.write(buf),
            Conn::Tls(stream) => stream.write(buf),
        }
    }

    fn flush(&mut self) -> io::Result<()> {
        match self {
            Conn::Plain(stream) => stream.flush(),
            Conn::Tls(stream) => stream.flush(),
        }
    }
}

struct HttpResponse {
    status: u16,
    headers: Vec<(String, String)>,
    body: Vec<u8>,
}

impl HttpResponse {
    fn header(&self, name: &str) -> Option<&str> {
        self.headers
            .iter()
            .find(|(key, _)| key.eq_ignore_ascii_case(name))
            .map(|(_, value)| value.as_str())
    }
}

