fn parse_request_url(transformed: &str) -> Result<Url, String> {
    match Url::parse(transformed) {
        Ok(url) => {
            if url.scheme() != "http" && url.scheme() != "https" {
                Err(format!(
                    "builder error for url ({}): URL scheme is not allowed",
                    url
                ))
            } else {
                Ok(url)
            }
        }
        Err(error) => Err(match error {
            url::ParseError::RelativeUrlWithoutBase => {
                "builder error: relative URL without a base".to_string()
            }
            url::ParseError::InvalidPort => "builder error: invalid port number".to_string(),
            url::ParseError::EmptyHost => "builder error: empty host".to_string(),
            url::ParseError::IdnaError => "builder error: invalid international domain name".to_string(),
            url::ParseError::InvalidIpv4Address => {
                "builder error: invalid IPv4 address".to_string()
            }
            url::ParseError::InvalidIpv6Address => {
                "builder error: invalid IPv6 address".to_string()
            }
            url::ParseError::InvalidDomainCharacter => {
                "builder error: invalid domain character".to_string()
            }
            url::ParseError::SetHostOnCannotBeABaseUrl => {
                "builder error: a cannot-be-a-base URL doesn’t have a host to set".to_string()
            }
            url::ParseError::Overflow => "builder error: URLs with more than 32 bits of data are not supported".to_string(),
            _ => format!("builder error: {}", error),
        }),
    }
}

fn connect_tls(host_connect: &str, host_name: &str, port: u16) -> io::Result<Conn> {
    let connect_arg = format!("{}:{}", host_connect, port);
    let mut child = Command::new("openssl")
        .args([
            "s_client",
            "-quiet",
            "-nocommands",
            "-ign_eof",
            "-connect",
            &connect_arg,
            "-servername",
            host_name,
            "-alpn",
            "http/1.1",
            "-verify_return_error",
            "-verify_hostname",
            host_name,
        ])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()?;
    let stdin = child.stdin.take();
    let stdout = child.stdout.take();
    Ok(Conn::Tls(Box::new(TlsStream {
        child,
        stdin,
        stdout,
    })))
}

fn http_get(url: &Url) -> Result<HttpResponse, String> {
    if url.scheme() != "http" && url.scheme() != "https" {
        return Err(format!(
            "builder error for url ({}): URL scheme is not allowed",
            url
        ));
    }
    let host = url
        .host_str()
        .ok_or_else(|| "builder error: empty host".to_string())?
        .to_string();
    let port = url.port_or_known_port().unwrap_or(if url.scheme() == "https" {
        443
    } else {
        80
    });
    let host_connect = if host.starts_with('[') && host.ends_with(']') {
        host[1..host.len() - 1].to_string()
    } else {
        host.clone()
    };

    let addresses: Vec<_> = (host_connect.as_str(), port)
        .to_socket_addrs()
        .map_err(|error| {
            format!(
                "error sending request for url ({}): error trying to connect: dns error: {}",
                url, error
            )
        })?
        .collect();
    if addresses.is_empty() {
        return Err(format!(
            "error sending request for url ({}): error trying to connect: dns error: failed to lookup address information: Name or service not known",
            url
        ));
    }

    let mut last_error: Option<io::Error> = None;
    let mut plain_stream: Option<TcpStream> = None;
    for address in &addresses {
        match TcpStream::connect(address) {
            Ok(stream) => {
                plain_stream = Some(stream);
                break;
            }
            Err(error) => last_error = Some(error),
        }
    }
    let plain_stream = match plain_stream {
        Some(stream) => stream,
        None => {
            return Err(format!(
                "error sending request for url ({}): error trying to connect: tcp connect error: {}",
                url,
                last_error.unwrap()
            ))
        }
    };

    let mut conn = if url.scheme() == "https" {
        drop(plain_stream);
        connect_tls(&host_connect, &host_connect, port).map_err(|error| {
            format!(
                "error sending request for url ({}): error trying to connect: {}",
                url, error
            )
        })?
    } else {
        Conn::Plain(plain_stream)
    };

    let path = if url.path().is_empty() { "/" } else { url.path() };
    let request_target = match url.query() {
        Some(query) => format!("{}?{}", path, query),
        None => path.to_string(),
    };
    let host_header = match url.port() {
        Some(explicit_port) => format!("{}:{}", host, explicit_port),
        None => host.clone(),
    };
    let request = format!(
        "GET {} HTTP/1.1\r\naccept: */*\r\nuser-agent: Mozilla/5.0 (Windows NT 6.3; WOW64; Trident/7.0; Touch; MAGWJS; rv:11.0) like Gecko\r\nhost: {}\r\n\r\n",
        request_target, host_header
    );
    conn.write_all(request.as_bytes()).map_err(|error| {
        format!(
            "error sending request for url ({}): client error (SendRequest): {}",
            url, error
        )
    })?;
    conn.flush().map_err(|error| {
        format!(
            "error sending request for url ({}): client error (SendRequest): {}",
            url, error
        )
    })?;

    let mut reader = BufReader::new(conn);
    let mut status_line = Vec::new();
    let read_count = reader.read_until(b'\n', &mut status_line).map_err(|error| {
        format!(
            "error sending request for url ({}): client error (SendRequest): {}",
            url, error
        )
    })?;
    if read_count == 0 {
        return Err(format!(
            "error sending request for url ({}): client error (SendRequest): connection closed",
            url
        ));
    }
    let status_line = String::from_utf8_lossy(&status_line).trim().to_string();
    let status: u16 = status_line
        .split_whitespace()
        .nth(1)
        .and_then(|value| value.parse().ok())
        .ok_or_else(|| {
            format!(
                "error sending request for url ({}): client error (SendRequest): invalid HTTP version",
                url
            )
        })?;

    let mut headers = Vec::new();
    loop {
        let mut line = Vec::new();
        let count = reader.read_until(b'\n', &mut line).map_err(|error| {
            format!(
                "error sending request for url ({}): client error (SendRequest): {}",
                url, error
            )
        })?;
        if count == 0 {
            break;
        }
        let line = String::from_utf8_lossy(&line).trim_end_matches(['\r', '\n']).to_string();
        if line.is_empty() {
            break;
        }
        if let Some((name, value)) = line.split_once(':') {
            headers.push((name.trim().to_string(), value.trim().to_string()));
        }
    }

    let response_for_headers = HttpResponse {
        status,
        headers,
        body: Vec::new(),
    };
    let mut body = Vec::new();
    let is_chunked = response_for_headers
        .header("transfer-encoding")
        .map(|value| value.to_lowercase().contains("chunked"))
        .unwrap_or(false);
    if is_chunked {
        loop {
            let mut size_line = Vec::new();
            reader.read_until(b'\n', &mut size_line).map_err(|error| {
                format!(
                    "error sending request for url ({}): client error (SendRequest): {}",
                    url, error
                )
            })?;
            let size_text = String::from_utf8_lossy(&size_line);
            let size_text = size_text.trim().split(';').next().unwrap_or("0");
            let size = usize::from_str_radix(size_text, 16).unwrap_or(0);
            if size == 0 {
                loop {
                    let mut trailer = Vec::new();
                    let count = reader.read_until(b'\n', &mut trailer).unwrap_or(0);
                    if count == 0 || trailer == b"\r\n" || trailer == b"\n" {
                        break;
                    }
                }
                break;
            }
            let start = body.len();
            body.resize(start + size, 0);
            reader.read_exact(&mut body[start..]).map_err(|error| {
                format!(
                    "error sending request for url ({}): client error (SendRequest): {}",
                    url, error
                )
            })?;
            let mut crlf = [0u8; 2];
            let _ = reader.read_exact(&mut crlf);
        }
    } else if let Some(length) = response_for_headers
        .header("content-length")
        .and_then(|value| value.parse::<usize>().ok())
    {
        body.resize(length, 0);
        reader.read_exact(&mut body).map_err(|error| {
            format!(
                "error sending request for url ({}): client error (SendRequest): {}",
                url, error
            )
        })?;
    } else if status != 204 && status != 304 {
        reader.read_to_end(&mut body).map_err(|error| {
            format!(
                "error sending request for url ({}): client error (SendRequest): {}",
                url, error
            )
        })?;
    }

    Ok(HttpResponse {
        status: response_for_headers.status,
        headers: response_for_headers.headers,
        body,
    })
}

fn fetch_plugins_inner(provided_url: &str) -> Result<Vec<Plugin>, String> {
    let transformed = format!(
        "{}/main/plugins.json",
        provided_url
            .trim_end_matches('/')
            .replace("github.com", "raw.githubusercontent.com")
    );
    let original_url = parse_request_url(&transformed)?;
    let mut current_url = original_url.clone();
    let mut requests_made = 0usize;

    loop {
        requests_made += 1;
        let response = http_get(&current_url)?;
        if [301, 302, 303, 307, 308].contains(&response.status) {
            if let Some(location) = response.header("location") {
                if requests_made >= 10 {
                    return Err(format!(
                        "error following redirect for url ({}): too many redirects",
                        original_url
                    ));
                }
                let next_url = current_url.join(location).map_err(|error| match error {
                    url::ParseError::RelativeUrlWithoutBase => {
                        "builder error: relative URL without a base".to_string()
                    }
                    _ => format!("builder error: {}", error),
                })?;
                if next_url.scheme() != "http" && next_url.scheme() != "https" {
                    return Err(format!(
                        "builder error for url ({}): URL scheme is not allowed",
                        next_url
                    ));
                }
                current_url = next_url;
                continue;
            }
        }

        if !(200..300).contains(&response.status) {
            println!(
                "Error: Received a {} status code from the server.",
                status_display(response.status)
            );
            process::exit(1);
        }

        let text = String::from_utf8_lossy(&response.body).into_owned();
        return serde_json::from_str::<Vec<Plugin>>(&text).map_err(|error| error.to_string());
    }
}

fn fetch_plugins(provided_url: &str) -> Vec<Plugin> {
    match fetch_plugins_inner(provided_url) {
        Ok(plugins) => plugins,
        Err(error) => {
            eprintln!(
                "[-] Error: Failed to parse plugins.json from the provided URL. Reason: {}",
                error
            );
            process::exit(1);
        }
    }
}

pub fn download_and_add_plugin(provided_url: &str) -> bool {
    let downloaded_plugins = fetch_plugins(provided_url);
    let mut existing_plugins = match load_plugins() {
        Some(plugins) => plugins,
        None => {
            println!("[-] Error: Failed to open plugins.json file.");
            return false;
        }
    };

    let mut duplicate_found = false;
    for plugin in &downloaded_plugins {
        if existing_plugins
            .iter()
            .any(|existing| existing.arg_long_name == plugin.arg_long_name)
        {
            println!(
                "[-] Error: Skipping Duplicate plugin found with arg_long_name: {}",
                plugin.arg_long_name
            );
            duplicate_found = true;
        }
    }
    if downloaded_plugins.len() == 1 && duplicate_found {
        return false;
    }

    let stored_source_url = provided_url.trim_end_matches('/').to_string();
    for mut plugin in downloaded_plugins {
        plugin.source_url = stored_source_url.clone();
        existing_plugins.push(plugin);
    }
    save_plugins(&existing_plugins);
    true
}

pub fn update_plugin(provided_url: &str) -> bool {
    let mut existing_plugins = load_plugins().unwrap_or_default();
    let normalized = normalize_url(provided_url);
    if !existing_plugins
        .iter()
        .any(|plugin| normalize_url(&plugin.source_url) == normalized)
    {
        println!(
            "[-] Error: No existing plugin found with the given URL: {}",
            provided_url
        );
        return false;
    }
    existing_plugins.retain(|plugin| normalize_url(&plugin.source_url) != normalized);
    save_plugins(&existing_plugins);
    download_and_add_plugin(provided_url)
}

pub fn update_all_plugins() {
    let plugins = load_plugins().unwrap_or_default();
    for plugin in plugins {
        if update_plugin(&plugin.source_url) {
            println!("[*] Updated Plugin: {}", plugin.source_url);
        } else {
            println!("[-] Failed to Update Plugin: {}", plugin.source_url);
        }
    }
}
