                    _ => {
                        println!(
                            "[-] Failed to open output file: {}. Error: {}",
                            current_file, error
                        );
                    }
                }
            }
            process::exit(1);
        }
    }
}

fn emit_match(
    content_type: &str,
    content: &str,
    line_number: usize,
    current_file: &str,
    config: &Config,
) {
    let formatted = if config.output.ends_with(".csv") {
        let mut parts: Vec<String> = Vec::new();
        if !config.hide {
            parts.push(content_type.to_string());
        }
        if config.display {
            parts.push(current_file.to_string());
        }
        if config.line {
            parts.push(line_number.to_string());
        }
        parts.push(content.to_string());
        parts.join(", ")
    } else {
        let identifier = if config.hide {
            String::new()
        } else if config.line || config.display {
            format!("{}, ", content_type)
        } else {
            format!("{}: ", content_type)
        };
        let file_part = if config.display {
            format!("file: {} ", current_file)
        } else {
            String::new()
        };
        let line_part = if config.line {
            format!(", line: {}", line_number)
        } else {
            String::new()
        };
        format!("{}{}{}{}", identifier, file_part, content, line_part)
    };

    emit_line(&formatted, config, current_file);
}

fn write_csv_header(config: &Config, current_file: &str) {
    let mut parts: Vec<&str> = Vec::new();
    if !config.hide {
        parts.push("content_type");
    }
    if config.display {
        parts.push("file");
    }
    if config.line {
        parts.push("line");
    }
    parts.push("data");
    emit_line(&parts.join(", "), config, current_file);
}

fn process_line(
    line: &str,
    line_number: usize,
    current_file: &str,
    patterns: &HashMap<String, Regex>,
    config: &Config,
    drop_regex: &Regex,
    filter_regex: &Regex,
) {
    if config.thorough {
        let mut seen: HashSet<String> = HashSet::new();
        for (content_type, regex) in patterns.iter() {
            for found in regex.find_iter(line) {
                let matched = found.as_str();
                if config.clean {
                    if passes_filters(
                        matched,
                        &config.drop_pattern,
                        drop_regex,
                        &config.filter_pattern,
                        filter_regex,
                    ) && seen.insert(matched.to_string())
                    {
                        emit_match(content_type, matched, line_number, current_file, config);
                    }
                } else {
                    if passes_filters(
                        line,
                        &config.drop_pattern,
                        drop_regex,
                        &config.filter_pattern,
                        filter_regex,
                    ) {
                        emit_match(content_type, line, line_number, current_file, config);
                    }
                    if passes_filters(
                        matched,
                        &config.drop_pattern,
                        drop_regex,
                        &config.filter_pattern,
                        filter_regex,
                    ) && seen.insert(matched.to_string())
                    {
                        emit_match(content_type, matched, line_number, current_file, config);
                    }
                }
            }
        }
        return;
    }

    for (content_type, regex) in patterns.iter() {
        if !regex.is_match(line) {
            continue;
        }
        if !config.clean
            && passes_filters(
                line,
                &config.drop_pattern,
                drop_regex,
                &config.filter_pattern,
                filter_regex,
            )
        {
            emit_match(content_type, line, line_number, current_file, config);
            return;
        }
        for found in regex.find_iter(line) {
            let matched = found.as_str();
            if passes_filters(
                matched,
                &config.drop_pattern,
                drop_regex,
                &config.filter_pattern,
                filter_regex,
            ) {
                emit_match(content_type, matched, line_number, current_file, config);
                return;
            }
        }
    }
}

fn process_lines<R: BufRead>(
    reader: R,
    current_file: &str,
    patterns: &HashMap<String, Regex>,
    config: &Config,
    drop_regex: &Regex,
    filter_regex: &Regex,
) {
    let mut line_number = 0usize;
    for line in reader.lines() {
        if let Ok(line) = line {
            line_number += 1;
            process_line(
                &line,
                line_number,
                current_file,
                patterns,
                config,
                drop_regex,
                filter_regex,
            );
        }
    }
}

fn handle_open_error(error: &io::Error, current_file: &str, ignore: bool) {
    if ignore {
        return;
    }
    match error.kind() {
        io::ErrorKind::PermissionDenied => {
            println!("[-] Permission denied for file: {}", current_file);
        }
        io::ErrorKind::NotFound => {
            println!("[-] Failed to open output file: {}", current_file);
        }
        _ => {
            println!(
                "[-] Failed to open output file: {}. Error: {}",
                current_file, error
            );
        }
    }
}

fn run_extraction(matches: &ArgMatches, plugins: &[Plugin]) {
    let start = Instant::now();

    let config = Config {
        file: get_string(matches, "file"),
        directory: get_string(matches, "directory"),
        output: get_string(matches, "output"),
        drop_pattern: get_string(matches, "drop"),
        filter_pattern: get_string(matches, "filter"),
        clean: get_bool(matches, "clean"),
        ignore: get_bool(matches, "ignore"),
        line: get_bool(matches, "count"),
        thorough: get_bool(matches, "thorough"),
        display: get_bool(matches, "display"),
        suppress: get_bool(matches, "suppress"),
        hide: get_bool(matches, "hide"),
        time: get_bool(matches, "time"),
    };

    let drop_regex = Regex::new(&config.drop_pattern).unwrap();
    let filter_regex = Regex::new(&config.filter_pattern).unwrap();

    let all_patterns = build_all_patterns(plugins);

    if config.output.ends_with(".csv") {
        write_csv_header(&config, &config.file);
    }

    if !config.file.is_empty() {
        if !Path::new(&config.file).exists() {
            if !config.ignore {
                println!("[-] File not found: {}", config.file);
            }
            process::exit(1);
        }
        let file = match File::open(&config.file) {
            Ok(file) => file,
            Err(error) => {
                handle_open_error(&error, &config.file, config.ignore);
                process::exit(1);
            }
        };
        let patterns = select_patterns(matches, &all_patterns);
        process_lines(
            BufReader::new(file),
            &config.file,
            &patterns,
            &config,
            &drop_regex,
            &filter_regex,
        );
    } else if !config.directory.is_empty() {
        let patterns = select_patterns(matches, &all_patterns);
        for entry in WalkDir::new(&config.directory) {
            if let Ok(entry) = entry {
                if entry.file_type().is_file() {
                    let path = entry.path().display().to_string();
                    match File::open(entry.path()) {
                        Ok(file) => {
                            process_lines(
                                BufReader::new(file),
                                &path,
                                &patterns,
                                &config,
                                &drop_regex,
                                &filter_regex,
                            );
                        }
                        Err(error) => {
                            handle_open_error(&error, &path, config.ignore);
                        }
                    }
                }
            }
        }
    } else {
        if !config.suppress {
            println!(
                "[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)"
            );
        }
        let patterns = select_patterns(matches, &all_patterns);
        let stdin = io::stdin();
        process_lines(
            stdin.lock(),
            &config.file,
            &patterns,
            &config,
            &drop_regex,
            &filter_regex,
        );
    }

    if config.time {
        let elapsed = start.elapsed().as_secs();
        println!(
            "[*] Time elapsed: {:02}h:{:02}m:{:02}s",
            elapsed / 3600,
            (elapsed % 3600) / 60,
            elapsed % 60
        );
    }
}

fn main() {
    let loaded_plugins = plugins::load_plugins().unwrap_or_default();
    let matches = build_command(&loaded_plugins).get_matches();

    if get_bool(&matches, "list") {
        plugins::list_plugins();
        process::exit(1);
    }

    let add = get_string(&matches, "add");
    if !add.is_empty() {
        if plugins::download_and_add_plugin(&add) {
            println!("[*] Download and added plugin: {}", add);
        }
        process::exit(1);
    }

    let remove = get_string(&matches, "remove");
    if !remove.is_empty() {
        plugins::remove_plugin(&remove);
        process::exit(1);
    }

    let update = get_string(&matches, "update");
    if !update.is_empty() {
        if update.to_lowercase() == "all" {
            plugins::update_all_plugins();
        } else if plugins::update_plugin(&update) {
            println!("[*] Updated Plugin: {}", update);
        }
        process::exit(1);
    }

    run_extraction(&matches, &loaded_plugins);
}
