fn ip_in_cidr(ip: &std::net::IpAddr, network: &std::net::IpAddr, prefix: u32) -> bool {
    match (ip, network) {
        (std::net::IpAddr::V4(ip), std::net::IpAddr::V4(network)) => {
            if prefix > 32 {
                return false;
            }
            if prefix == 0 {
                return true;
            }
            let mask = u32::MAX << (32 - prefix);
            (u32::from(*ip) & mask) == (u32::from(*network) & mask)
        }
