            if prefix > 128 {
                return false;
            }
            if prefix == 0 {
                return true;
            }
            let mask = u128::MAX << (128 - prefix);
            (u128::from(*ip) & mask) == (u128::from(*network) & mask)
        }
        _ => false,
    }
}

fn no_proxy_matches(url: &Url) -> bool {
    let value = match std::env::var("NO_PROXY") {
        Ok(value) => value,
        Err(_) => match std::env::var("no_proxy") {
            Ok(value) => value,
            Err(_) => return false,
        },
    };
    let host = match url.host_str() {
        Some(host) => host.trim_start_matches('[').trim_end_matches(']'),
        None => return false,
    };
    let host_ip = host.parse::<std::net::IpAddr>().ok();

    for raw_entry in value.split(',') {
        let entry = raw_entry.trim();
        if entry.is_empty() {
            continue;
        }
        if entry == "*" {
            return true;
        }
        if let Some((network_text, prefix_text)) = entry.split_once('/') {
            if let (Some(ip), Ok(network), Ok(prefix)) = (
                host_ip,
                network_text.parse::<std::net::IpAddr>(),
                prefix_text.parse::<u32>(),
            ) {
                if ip_in_cidr(&ip, &network, prefix) {
                    return true;
                }
            }
            continue;
        }
        if let (Some(ip), Ok(entry_ip)) = (host_ip, entry.parse::<std::net::IpAddr>()) {
            if ip == entry_ip {
                return true;
            }
            continue;
        }
        if host_ip.is_some() {
            continue;
        }
        let domain = entry.strip_prefix('.').unwrap_or(entry);
        if host == domain || host.ends_with(&format!(".{}", domain)) {
            return true;
        }
    }
    false
}

