    let connect_arg = if host_connect.contains(':') && !host_connect.starts_with('[') {
        format!("[{}]:{}", host_connect, port)
    } else {
        format!("{}:{}", host_connect, port)
    };
    let is_ip = host_name.parse::<std::net::IpAddr>().is_ok();
    let mut command = Command::new("openssl");
    command.args([
        "s_client",
        "-quiet",
        "-nocommands",
        "-ign_eof",
        "-connect",
        &connect_arg,
    ]);
    if is_ip {
        command.args(["-verify_ip", host_name]);
    } else {
        command.args(["-servername", host_name, "-verify_hostname", host_name]);
    }
    command.args(["-alpn", "http/1.1", "-verify_return_error"]);
    spawn_tls_command(command)
}

fn connect_tls_via_http_proxy(
    proxy: &Url,
    target_host_connect: &str,
    target_host_name: &str,
    target_port: u16,
) -> io::Result<Conn> {
    let connect_arg = if target_host_connect.contains(':') && !target_host_connect.starts_with('[') {
        format!("[{}]:{}", target_host_connect, target_port)
    } else {
        format!("{}:{}", target_host_connect, target_port)
    };
    let proxy_host = proxy.host_str().unwrap_or("");
    let proxy_port = proxy.port_or_known_default().unwrap_or(80);
    let proxy_arg = if proxy_host.contains(':') && !proxy_host.starts_with('[') {
        format!("[{}]:{}", proxy_host, proxy_port)
    } else {
        format!("{}:{}", proxy_host, proxy_port)
    };
    let mut command = Command::new("openssl");
    command.args([
        "s_client",
        "-quiet",
        "-nocommands",
        "-ign_eof",
        "-proxy",
        &proxy_arg,
        "-connect",
        &connect_arg,
    ]);
    if !proxy.username().is_empty() || proxy.password().is_some() {
        let user = String::from_utf8_lossy(&percent_decode(proxy.username())).into_owned();
        let password = String::from_utf8_lossy(&percent_decode(proxy.password().unwrap_or(""))).into_owned();
        command.args(["-proxy_user", &user]);
        command.arg("-proxy_pass").arg(format!("pass:{}", password));
    }
    if target_host_name.parse::<std::net::IpAddr>().is_ok() {
        command.args(["-verify_ip", target_host_name]);
    } else {
        command.args([
            "-servername",
            target_host_name,
            "-verify_hostname",
            target_host_name,
        ]);
    }
    command.args(["-alpn", "http/1.1", "-verify_return_error"]);
    spawn_tls_command(command)
}
