fn=r'''fn decode_response_body(response: &HttpResponse) -> String {
    let body = &response.body;
    if body.starts_with(&[0xFF, 0xFE]) {
        return decode_utf16(&body[2..], true);
    }
    if body.starts_with(&[0xFE, 0xFF]) {
        return decode_utf16(&body[2..], false);
    }
    if body.starts_with(&[0xEF, 0xBB, 0xBF]) {
        return String::from_utf8_lossy(&body[3..]).into_owned();
    }

    let mut charset = "";
    if let Some(content_type) = response.header("content-type") {
        for parameter in content_type.split(';').skip(1) {
            if let Some((name, value)) = parameter.split_once('=') {
                if name.trim().eq_ignore_ascii_case("charset") {
                    charset = value.trim().trim_matches('"');
                    break;
                }
            }
        }
    }

    match charset.to_lowercase().as_str() {
        "utf-16" | "utf-16le" | "ucs-2" | "iso-10646-ucs-2" | "csunicode" => {
            decode_utf16(body, true)
        }
        "utf-16be" => decode_utf16(body, false),
        "windows-1252"
        | "iso-8859-1"
        | "iso8859-1"
        | "iso88591"
        | "latin1"
        | "l1"
        | "us-ascii"
        | "ascii"
        | "ansi_x3.4-1968"
        | "iso-ir-100"
        | "csisolatin1" => decode_windows1252(body),
        _ => String::from_utf8_lossy(body).into_owned(),
    }
}

fn decode_utf16(bytes: &[u8], little_endian: bool) -> String {
    let mut units: Vec<u16> = Vec::with_capacity(bytes.len() / 2);
    let mut chunks = bytes.chunks_exact(2);
    for chunk in &mut chunks {
        units.push(if little_endian {
            u16::from_le_bytes([chunk[0], chunk[1]])
        } else {
            u16::from_be_bytes([chunk[0], chunk[1]])
        });
    }
    let mut decoded: String = char::decode_utf16(units.into_iter())
        .map(|result| result.unwrap_or(char::REPLACEMENT_CHARACTER))
        .collect();
    if !chunks.remainder().is_empty() {
        decoded.push(char::REPLACEMENT_CHARACTER);
    }
    if let Some(stripped) = decoded.strip_prefix('\u{feff}') {
        decoded = stripped.to_string();
    }
    decoded
}

fn decode_windows1252(bytes: &[u8]) -> String {
    const HIGH: [u32; 32] = [
        0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
        0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0x008D, 0x017D, 0x008F,
        0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
        0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178,
    ];
    bytes
        .iter()
        .map(|&byte| {
            if (0x80..0xA0).contains(&byte) {
                char::from_u32(HIGH[(byte - 0x80) as usize]).unwrap()
            } else {
                byte as char
            }
        })
        .collect()
}

